def load(p):return json.loads(p.read_text(encoding='utf-8'))
def new(p,v):assert not p.exists(),str(p);p.write_text(json.dumps(v,ensure_ascii=False,separators=(',',':'),allow_nan=False)+'\n',encoding='utf-8')
def main():
    assert not (R/'FACTS.json').exists();pins=[{'path':str(p),'bytes':p.stat().st_size,'SHA':sha(p)}for p in PATHS];old,newv=load(PATHS[0]),load(PATHS[1]);source=PATHS[4].read_text(encoding='utf-8')
    assert "self.radius=np.asarray(m.geom_rbound[self.ids],float).copy()+1e-8"in source and "low=(xyz-self.radius[:,None]).min(axis=0)"in source and "self.minimum_final_x=float(low[0])"in source
    assert old['first_transverse_bar']==newv['first_transverse_bar'] and old['DR']==newv['DR'];rows={}
