    a=rows['baseline_R60'];b=rows['candidate_R62'];delta={'root_POST_X_m':b['root_POST_xyz_m'][0]-a['root_POST_xyz_m'][0],'conservative_bound_minX_m':b['final_private_collision_bounds']['min_xyz_m'][0]-a['final_private_collision_bounds']['min_xyz_m'][0],'root_POST_Z_m':b['root_POST_xyz_m'][2]-a['root_POST_xyz_m'][2],'mixed_clock_rootPOST_minus_bound_offset_m':b['rootPOST_X_minus_boundMinX_m_NOT_exact_same_time_body_extent']-a['rootPOST_X_minus_boundMinX_m_NOT_exact_same_time_body_extent']}
    assert abs(delta['conservative_bound_minX_m']-(delta['root_POST_X_m']-delta['mixed_clock_rootPOST_minus_bound_offset_m']))<1e-12
    facts={'status':'TWO_SMALL_RESULT_FINAL_SCOPE_MARGIN_AUDIT_NOT_SHAPE_CONTACT_OR_CAUSAL_MODEL','cases':rows,'candidate_minus_baseline':delta,'DR_receipts_equal_offline_metadata_only':True,'calculation_role':'arithmetic decomposition, mixed rootPOST and cached bounds clocks explicit; not posture/mesh reconstruction','bound_semantics':'union of compiled-rbound+1e-8 collision-geom spheres; positive minX-back certifies all enclosed x beyond bar, negative margin only fails certificate, not proof of shape intersection/contact','unknowns':['whichgeom attains minX not saved','actual34geom directional support/actualmeshminX not saved','not proved merely a conservative false-negative nor proved actual bar overlap','cause of root stopping3.8cm earlier not identified without trace; separate agent handles it'],'old_gates_and_scores_unchanged':True,'no_gain_or_target_selection':True,'source_small_SHA_before':pins,'raw_othercase_H5_asset_model_PHY_QA_Git_agents_reads_or_calls':False,'PH8pending':True}
    new(R/'FACTS.json',facts)
    md=f'''# R62 seed4610 final-scope regression：仅small result/offline\n\n| 指标 | R60 baseline | R62 AIRref |\n|---|---:|---:|\n|原main/local gate|{a['main_original_gate']}/{a['local_original_gate']}|{b['main_original_gate']}/{b['local_original_gate']}|\n|guide/hard ticks|{a['guide_ticks']}/{a['hard_ticks']}|{b['guide_ticks']}/{b['hard_ticks']}|\n|endstable s|{a['end_stable_s']!r}|{b['end_stable_s']!r}|\n|mainfirstflightrear s|{a['firstflight_mainrear_s']!r}|{b['firstflight_mainrear_s']!r}|\n|root POST x/y/z m|{a['root_POST_xyz_m']}|{b['root_POST_xyz_m']}|\n|root POST yaw/pitch/roll rad|{a['root_POST_yaw_pitch_roll_rad']}|{b['root_POST_yaw_pitch_roll_rad']}|\n|body velocity POST B m/s|{a['body_velocity_POST_B_m_s']}|{b['body_velocity_POST_B_m_s']}|\n|compiled-sphere minX m|{a['final_private_collision_bounds']['min_xyz_m'][0]!r}|{b['final_private_collision_bounds']['min_xyz_m'][0]!r}|\n|minX−firstbarback m|{a['conservative_minX_margin_m']!r}|{b['conservative_minX_margin_m']!r}|\n|exact main-rear−barback m|{a['exact_main_rear_margin_m']!r}|{b['exact_main_rear_margin_m']!r}|\n\n相同firstbar011 backX={b['bar']['back_x_m']!r}m。新root实际progress={b['progress_m']!r}m，而root POST x={b['root_POST_xyz_m'][0]!r}，不要混用progress与全机器人minX。原local唯一新增失败是final-full-collision-bound-behind；nextbar未到达仍True。\n\n新bound minX比旧少{abs(delta['conservative_bound_minX_m'])*1000:.6f}mm，root POST x少{abs(delta['root_POST_X_m'])*1000:.6f}mm；rootPOST−boundminX offset只多{delta['mixed_clock_rootPOST_minus_bound_offset_m']*1000:.6f}mm。这是保存数值的算术分解，不是相同tick的真实后伸长度或导致停止的控制机制；source bounds时钟={b['bounds_cached_stage_s']!r}，rootPOST={b['root_POST_time_s']!r}，相差约.5ms。\n\n**保守证书失败≠实测bar接触或真实mesh重叠。** source只对34个collision geom的compiledrbound+1e−8球求union AABB，非碰撞shape或方向精确全mesh。旧margin+29.360648mm，新−8.915685mm，只证明原保守whole-robot-behind门槛未通过；并不能证明真实shape已过/未过。argmin geom未存，不猜是chassis/guide，不把近似界解释为实际姿态故障。finalpitch约.01rad，两案rootZ差仅{delta['root_POST_Z_m']!r}m，但这也不证明相同完整关节/mesh姿态。\n\n保留原localFalse与全部gate，不放宽/改分、不选gain或新目标。未读任何raw/trace/H5/mesh/模型/QA/新PHY/Git/newagent；仅两个result、新report和grade_rows源。其他agent独立trace解释不在本任务。细值/时钟/sourceSHA见[FACTS](<FACTS.json>)、[receipt](<RECEIPT.json>)。PH8pending。\n'''
    (R/'REPORT.md').write_text(md,encoding='utf-8');assert all(sha(Path(p['path']))==p['SHA']for p in pins)
    receipt={'status':'SMALL_RESULT_ONLY_SCOPE_MARGIN_REGRESSION_RECONCILED_NOT_MESH_OR_CONTACT_PROOF','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'sources_before_after_SHA_equal':pins,'script_SHA':sha(Path(__file__)),'facts_SHA':sha(R/'FACTS.json'),'report_SHA':sha(R/'REPORT.md'),'new_physics_geometry_QA_Git_agents_raw_H5_calls':0,'old_files_thresholds_scores_changed':False,'actual_shape_overlap_unknown':True,'PH8pending':True};new(R/'RECEIPT.json',receipt);assert sum(p.read_text(encoding='utf-8').count('\n')for p in(R/'REPORT.md',R/'FACTS.json',R/'RECEIPT.json'))<=70
    print(json.dumps({'old_new_margin_m':[a['conservative_minX_margin_m'],b['conservative_minX_margin_m']],'candidate_minus_baseline':delta,'root_pose_clock_gap_s':b['post_minus_bounds_time_s'],'REPORT_SHA':sha(R/'REPORT.md'),'FACTS_bytes':(R/'FACTS.json').stat().st_size,'receipt_SHA':sha(R/'RECEIPT.json'),'total_report_JSON_receipt_lines':sum(p.read_text(encoding='utf-8').count('\n')for p in(R/'REPORT.md',R/'FACTS.json',R/'RECEIPT.json')),'qualification':'original gate unchanged; no actualshape overlap claim'},ensure_ascii=False,indent=2))
